function taskRecoveryFindHeaderIndex_(headers, aliases) {
  const normalizedHeaders = (headers || []).map(function(header) {
    return taskRecoveryNormalizeHeader_(header);
  });

  // Alias order is authoritative. When both Desired and Current columns
  // exist, callers can explicitly prefer Desired by listing it first.
  for (let a = 0; a < (aliases || []).length; a++) {
    const normalizedAlias = taskRecoveryNormalizeHeader_(aliases[a]);
    const idx = normalizedHeaders.indexOf(normalizedAlias);
    if (idx !== -1) {
      return idx;
    }
  }

  return -1;
}

