  const calendarIds = taskRecoveryGetCalendarIds_(context);
  const rawEventId = String(context.eventId || '').trim();
  const normalizedEventId = rawEventId.replace(/@google\.com$/i, '');

  if (!calendarIds.length) {
    throw new Error('No Calendar ID could be resolved for ' + context.division + '.');
  }

  for (let i = 0; i < calendarIds.length; i++) {
    const calendar = CalendarApp.getCalendarById(calendarIds[i]);
    if (!calendar) continue;

    const directCandidates = taskRecoveryUniqueStrings_([
      rawEventId,
      normalizedEventId
    ]);

    for (let d = 0; d < directCandidates.length; d++) {
      try {
        const direct = calendar.getEventById(directCandidates[d]);

        if (direct) {
          return taskRecoveryCalendarEventSnapshot_(calendarIds[i], direct);
        }
      } catch (err) {
        // Fall through to bounded scan.
      }
    }

    const window = taskRecoveryBuildEventScanWindow_();
    const events = calendar.getEvents(window.start, window.end);

    for (let e = 0; e < events.length; e++) {
      const foundRaw = String(events[e].getId() || '').trim();
      const foundNormalized = foundRaw.replace(/@google\.com$/i, '');

      if (
        foundRaw === rawEventId ||
        foundRaw === normalizedEventId ||
        foundNormalized === rawEventId ||
        foundNormalized === normalizedEventId
      ) {
        return taskRecoveryCalendarEventSnapshot_(calendarIds[i], events[e]);
      }
    }
  }

  throw new Error(
    'Fresh Calendar event not found for Event ID ' + context.eventId +
    '. CREATE / RECREATE blocked.'
  );
}
